GUIDE_DATA.glossary = [
  { id: "seatbelt", term: "Seatbelt", def: "Apple's own sandboxing system, built into macOS. A program runs under a profile, a list of rules each allowing or denying one kind of action (read this file, connect to this address); the kernel checks every rule itself, for every file and network call the program makes.", entity: "sandbox" },
  { id: "bubblewrap", term: "bubblewrap", def: "A small Linux program (`bwrap`) that starts a command with an almost-empty filesystem and gives it back only the exact files and directories it's told to: everything else simply isn't there, not merely blocked.", entity: "sandbox" },
  { id: "namespace", term: "Kernel namespace", def: "A Linux kernel feature that gives one process its own private version of something the whole machine normally shares, such as its list of running processes or its network, as if it were the only thing on the machine. bubblewrap sets up a fresh one before the agent's command starts.", entity: "sandbox" },
  { id: "proc-environ", term: "A process's environment, under /proc", def: "On Linux, a running process's environment variables (which can include keys) sit in a file the kernel exposes at `/proc/<its process id>/environ`, normally readable by any process of the same user. The sandbox's private process list on Linux exists to close this, and for no other reason.", entity: "sandbox" },

  { id: "accept", term: "Accept result", def: "The held-out suite's result for the workspace after a story, over every story built so far. Also called the live score. Reported as new work, regressions, repairs and cumulative; n/a, not 0/0, when a pack has no suite.", entity: "accept", see: ["live-score", "score-record"] },
  { id: "agent", term: "Agent", def: "A language model driving a coding client: it reads the prompt, then uses tools to read, edit and write files and run commands until it believes the story is done.", see: ["client"] },
  { id: "agent-sandbox", term: "agent-sandbox", def: "A Rust tool that runs a command with the least access it needs: write only to its own directory, network only to named ports and hosts. Every agent runs in it, on every machine.", entity: "sandbox", auto: ["agent-sandbox"], see: ["sandbox"] },
  { id: "anomaly-log", term: "Anomaly log", def: "`ops/anomaly-tracking.md`: the fault log. Each internal fault becomes a numbered entry (A-001…) in one of six buckets and stays open until fixed or explained.", entity: "anomaly-log", auto: ["anomaly log"], see: ["bucket", "monitor"] },
  { id: "attempt", term: "Attempt", def: "One harness process working on a story. A harness restart mid-story starts a new attempt in the same agent session; the story's totals are summed over attempts.", entity: "attempt", see: ["session"] },
  { id: "base", term: "Base (of a partial rerun)", def: "The code a partial rerun starts from: another run's workspace as it was when the story before ended. Its held-out result is measured first so regressions and repairs count.", see: ["partial-rerun"] },
  { id: "benchmarker", term: "Benchmarker", def: "The results page in `tools/benchmarker`. It shows results only, never faults; a run marked invalid is not in it.", entity: "benchmarker", auto: ["benchmarker"] },
  { id: "blinded-grading", term: "Blinded grading", def: "An independent grader compares two builds' code without knowing which setup made which: the builds are labelled A and B in random order, names are scrubbed, and the key is kept outside the package.", auto: ["blinded grader", "blinded grading"], see: ["judge"] },
  { id: "bucket", term: "Bucket", def: "The class of an anomaly-log entry: internal bug, genuine LLM behaviour, stuck job, broken pipeline, environment, or unexplained.", see: ["anomaly-log"] },
  { id: "build-score-judge", term: "Build, score, judge", def: "The three stages of a result, each owned by someone different: the agent builds on a bench machine; the held-out suite scores after the run; a person judges whether each scored verdict was right.", see: ["judge", "score-record"] },
  { id: "bundle", term: "workspace.bundle", def: "A git bundle of the agent's whole workspace history, written at the end of a run. Every story's code can be rebuilt from it, so a score can be reproduced.", entity: "finalize", see: ["finalize"] },
  { id: "cap", term: "Story cap", def: "The limit on a story: 4 hours of agent time, or (on main) a second stop without a verified finish. A story ended at the cap is recorded PARTIAL with the work committed by the harness.", see: ["partial"] },
  { id: "cgroup", term: "cgroup", def: "A Linux kernel group of processes. The harness runs each agent session in its own so that everything the agent starts can be listed, limited and killed, even after its parent dies.", entity: "containment", see: ["containment"] },
  { id: "claude-code", term: "Claude Code", def: "Anthropic's coding client. It is the client of the reference models (Opus 5.5, Sonnet 5.5). The provider withholds its thinking text.", entity: "client", see: ["reference-model"] },
  { id: "client", term: "Client", def: "The coding agent program (pi, OpenCode or Claude Code) that sends the prompt and tools to the model and runs the tool calls. The harness runs it headless.", entity: "client", see: ["agent", "pi"] },
  { id: "combination", term: "Combination", def: "One tested pairing of model, engine, machine, client and settings, named by its folder path under `combinations/`.", entity: "combination", see: ["engine", "model", "machine"] },
  { id: "complete-run", term: "Complete run", def: "A run that finished, has a record for every story in its scope, and has its score of record under the current suite. A low score is still complete. A partial rerun never is. The benchmarker's **Complete runs** switch shows only these, on every page.", auto: ["complete run", "complete runs"], see: ["score-record", "benchmarker"] },
  { id: "compaction", term: "Compaction", def: "The client summarising the conversation to make room when it nears the context limit. It costs a model call and discards the prompt cache.", entity: "compaction", auto: ["compaction", "compactions"] },
  { id: "containment", term: "Containment", def: "On Linux, keeping every process the agent starts in a cgroup the harness owns. On macOS the harness cleans up by process group.", entity: "containment", see: ["cgroup"] },
  { id: "context-window", term: "Context window", def: "How many tokens the model can hold at once: 128k on most combinations (20k on the 16 GB one, too small for agentic coding). Chosen with the engine and the client's compaction threshold together.", see: ["compaction"] },
  { id: "lake", term: "Lake", def: "The host's raw, byte-for-byte copies of the files a run leaves on its machine and never pushes, pulled by `dbench collect` into the private repo's `state/collected/`, with `collection.json` beside each run saying what was collected and whether the run is complete.", entity: "collection", auto: ["the lake"] },
  { id: "warehouse", term: "Warehouse", def: "The conversation database, `conversations.db`: every conversation parsed into rows, with the model server's requests and the machine's readings placed in it, and an events stream with one millisecond time axis that the conversation API pages over.", entity: "conversation-db", auto: ["the warehouse", "conversation database"] },
  { id: "collector", term: "Collector", def: "`dbench collect`: the host's loop that pulls each run's machine-only files into the lake (pull and diff, never push), keeps the warehouse current, and serves the conversation API.", entity: "collector", auto: ["the collector"] },
  { id: "engine-request", term: "Engine request", def: "One request the model server finished, by its own log: what it read and generated, how long prefill and decode took, and how many drafted tokens were accepted; placed in a story by time, or matched to a call by its token counts.", entity: "engine-request", auto: ["engine request", "engine requests"] },
  { id: "cursor", term: "Cursor", def: "Opaque text naming a place in a story's events stream (its time and ord). The time-range form of the conversation API pages with it, contiguous by construction; the open-ended form returns everything ingested after it and the latest one to ask after next.", auto: ["cursor"] },
  { id: "conversation", term: "Conversation (events)", def: "The agent's complete event log for a story, every reply, thought, tool call and result, time-stamped on arrival and published whole.", entity: "conversation", auto: ["conversation profile"], see: ["time-split"] },
  { id: "credential-scan", term: "Credential scan", def: "The check that replaces credentials in anything staged for a public commit with a marker naming what was found and how long, never the value.", entity: "credential-scan", auto: ["credential scan", "credential scanner"] },
  { id: "dbench", term: "dbench", def: "The Rust controller that queues benchmark jobs on each machine, restarts and recovers them, and reports status.", entity: "dbench", auto: ["dbench"], see: ["node-server", "job"] },
  { id: "decode", term: "Decode (generation)", def: "The model producing new tokens, one after another. Engine decode speed is output tokens over the model's own generation time.", see: ["prefill", "tok-s"], auto: ["decode speed"] },
  { id: "done-line", term: "DONE line", def: "The line `STORY <id> DONE <commit hash>` that the agent must end its last reply with. A story is finished only if the hash is the start of the workspace's HEAD and nothing is uncommitted.", entity: "stop-message", see: ["stop-rule"] },
  { id: "draft-head", term: "Draft head (MTP)", def: "A small extra part of some models that proposes several next tokens at once, which the main model then checks. Used for speculative decoding.", see: ["speculative-decoding"], auto: ["MTP"] },
  { id: "engine", term: "Engine", def: "The server program that loads a model and serves an OpenAI-compatible API with tool calling: llama.cpp, MTPLX, mlx-serve, gufo, SGLang.", entity: "engine", see: ["combination"] },
  { id: "epic", term: "Epic", def: "A group of related stories in a spec, with 'Depends on' lines that fix the build order.", entity: "scope", see: ["scope"] },
  { id: "finalize", term: "Finalize", def: "The end-of-run step that bundles the workspace, repairs stale records, re-scores the final build and writes `finalize.json`.", entity: "finalize", auto: ["finalize.py"], see: ["score-record", "sweep"] },
  { id: "flaky", term: "Flaky test", def: "A held-out test whose result changed between the three scorings. Counted both ways: failed first and passed first.", see: ["rescore"] },
  { id: "from-story", term: "Partial-rerun options (--only, --from-story)", def: "Partial-rerun options: `--only N` runs one story on another run's code; `--from-story N` runs story N and every later story, each on the one before.", entity: "partial-rerun", see: ["partial-rerun"] },
  { id: "gate", term: "Gate", def: "The agent's own checks (`build`, `typecheck`, `test:*`) run by the harness after each story. Green means the agent's tests passed, not that the spec is met.", entity: "gate" },
  { id: "gufo", term: "gufo", def: "A single-model inference engine for the Strix Halo chip, run from a container image. One of the engines compared.", entity: "engine", auto: ["gufo"] },
  { id: "guard", term: "Live-versus-record guard", def: "The check in finalize that compares a re-score with the run's live score of the same code: more than 3 tests apart, a different number of tests, or one shared error behind all failures is flagged and not recorded.", entity: "score-record", see: ["score-record"] },
  { id: "harness", term: "Harness", def: "The code in `benchmarks/spec-bench/harness/` that runs a benchmark: sets up the workspace, starts the engine, drives the client, guards the machine, scores and records.", entity: "harness" },
  { id: "harness-release", term: "Harness release", def: "A git tag `harness-v<date>.<n>` on main, made only after every check passes. A node runs the newest release, not main.", entity: "harness-release", auto: ["harness release"], see: ["hold"] },
  { id: "heldout", term: "Held-out suite", def: "The pack's private browser tests that the agent never sees. Published only as counts. This guide does not describe what any test checks.", entity: "heldout", auto: ["held-out suite", "held-out tests", "held-out test"] },
  { id: "hold", term: "Hold (and release of a node)", def: "`dbench hold` stops new jobs starting on a node; the running job finishes. `dbench release` ends the hold. Not a harness release.", entity: "hold", see: ["harness-release"] },
  { id: "install", term: "Install", def: "What the installer leaves on a machine for one combination, including the manifest `install.env` that the harness and dbench read.", entity: "install" },
  { id: "intervention", term: "Intervention", def: "Anything the harness or an operator does to a story that the agent did not ask for: the stop message, a resume after an engine fault, a killed hung tool, a story ended at its cap, an operator skip.", entity: "intervention" },
  { id: "archived-run", term: "Archived run", def: "A run superseded by a later version of its pack: only `archived.json` stays in its run directory, and it is kept out of the lake, the warehouse, the analytics file and the benchmarker.", entity: "archived-run", auto: ["archived run", "archived runs"] },
  { id: "invalid-run", term: "Invalid run", def: "A run marked `invalid` in `run.json` because its result cannot stand. It is skipped by the re-score sweep and not shown in the benchmarker.", entity: "invalid-run", auto: ["invalid run", "invalid runs"] },
  { id: "job", term: "Job", def: "One dbench execution of a run, waiting in a node's queue: queued, running, done, failed or cancelled.", entity: "job" },
  { id: "judge", term: "Judging", def: "A person watching a recording of each held-out test and marking whether the scored pass or fail was right. It validates the scoring. (A blinded AI grader, below, compares code quality instead.)", entity: "judgement", see: ["blinded-grading", "build-score-judge"] },
  { id: "partial-rerun", term: "Partial rerun", def: "A diagnostic that runs a story, or the rest of a scope, on another finished run's code. Labelled diagnostic and never mixed with full runs.", entity: "partial-rerun", auto: ["partial-rerun"] },
  { id: "live-score", term: "Live score", def: "The held-out result taken in the agent's own workspace right after a story. It shows a run's course; it is not the score of record.", entity: "accept", auto: ["live score", "live scores"], see: ["score-record"] },
  { id: "llamacpp", term: "llama.cpp", def: "An open-source inference engine with CUDA, Vulkan and Metal back ends. Several combinations use it, some on a fork or an unmerged pull request for the MTP head.", entity: "engine", auto: ["llama.cpp"] },
  { id: "machine", term: "Machine", def: "The hardware a combination was measured on, named by hardware: the RTX 4090 machine, the Strix Halo box, the M5 Max. In dbench, a machine running `dbench serve` is a node.", entity: "machine", see: ["node"] },
  { id: "machine-guard", term: "Machine guard", def: "The check that stops a story when swap grows by more than 4 GB or free memory falls below 8%, exiting 75 so dbench waits for the machine to recover.", entity: "machine-guard", see: ["unfit"] },
  { id: "metrics-json", term: "metrics.json", def: "The run's per-story record: agent totals, time split, conversation profile, gate and held-out counts, provenance. Every field is listed in `TELEMETRY.md`.", entity: "run", auto: ["metrics.json"] },
  { id: "model", term: "Model", def: "The weights at one quantisation: Qwen3.8 27B, Qwen3.8 Flash-Next, the Swift 1.0 and 1.5 retrains of the 27B; and the reference models Claude Opus 5.5 and Sonnet 5.5.", entity: "model" },
  { id: "monitor", term: "Monitor", def: "The scheduled detector and unattended triage in `ops/monitor/` that find faults and write them to the anomaly log. It never fixes code or touches jobs.", entity: "monitor", auto: ["the monitor"] },
  { id: "mlx-serve", term: "mlx-serve", def: "A native Zig and MLX inference server for Apple silicon. One of the engines compared.", entity: "engine", auto: ["mlx-serve"] },
  { id: "mtplx", term: "MTPLX", def: "An inference engine for Apple silicon, installed from PyPI, with MTP speculative decoding. One of the engines compared; the README marks it \"not recommended at present\" (27 September 2026) after memory problems at compaction.", entity: "engine", auto: ["MTPLX"] },
  { id: "node", term: "Node", def: "A bench machine running `dbench serve`.", entity: "machine", see: ["node-server"] },
  { id: "node-server", term: "Node server", def: "`dbench serve`: the queue and API on one bench machine.", entity: "node-server", auto: ["node server"] },
  { id: "not-comparable", term: "Not comparable", def: "A story run marked as not the same work as that story in other runs, so story-by-story comparisons leave it out. Its figures, its run's total and its score stand.", entity: "not-comparable", auto: ["not comparable", "not-comparable"] },
  { id: "nudge", term: "Nudge", def: "The old name for what the harness sent when the agent stopped without a commit: 'Continue with the task from where you left off' (release 1 adds a reminder to commit), up to five times. The stop message replaces it on main.", entity: "stop-message", see: ["stop-message"] },
  { id: "opencode", term: "OpenCode", def: "A coding client used for earlier runs. The benchmark now uses pi.", entity: "client", auto: ["OpenCode"] },
  { id: "pack", term: "Pack", def: "One benchmark: a spec of stories, an optional held-out suite, a prompt template and a `bench.json`. Vidi and Todoodle are packs.", entity: "pack", see: ["spec"] },
  { id: "pack-ref", term: "pack_ref", def: "The tag of the private repo's suite that a pack is scored with. The version recorded is the tag that was scored.", entity: "heldout", auto: ["pack_ref"], see: ["suite-version"] },
  { id: "partial", term: "PARTIAL", def: "A story that ended early: at the story cap, on a second stop after the stop message (on main), or by an operator skip. Later stories built on it are noted in their prompts and counted apart.", entity: "story-run", see: ["done", "cap"] },
  { id: "done", term: "DONE (story status)", def: "A story the agent finished by itself: under the stop rule (on main), with a verified DONE line; in release 1, with a commit since the story began.", entity: "story-run", see: ["partial", "done-line"] },
  { id: "pi", term: "pi", def: "The coding client the benchmark uses for local models (pi.dev). Every v2 run of a local model uses pi 0.87.1, so client versions do not differ between stacks.", entity: "client", see: ["client"] },
  { id: "prefill", term: "Prefill", def: "The model reading its input before it generates. Engine prefill speed is fresh input tokens over the model's own reading time.", see: ["decode"] },
  { id: "preflight", term: "Preflight", def: "The check before a run that the agent's toolchain works inside the sandbox: `npm install`, `vite build`, `wrangler dev` and Chromium loading a page.", entity: "sandbox", auto: ["preflight"] },
  { id: "private-repo", term: "Private repo", def: "`awesome-local-ai-bench-private`: the held-out suites, grading briefs, blinded packages and the held-out detail of every run. Checked out next to this repo on each bench machine.", entity: "private-repo", auto: ["private repo"] },
  { id: "profile", term: "Profile", def: "A named row of a combination's `profiles.tsv`: context size, KV type, whether vision is on, and the measured memory it needs.", entity: "settings" },
  { id: "progress-file", term: "PROGRESS.md", def: "The agent's own account of where each task stands (todo, doing, done, blocked). A claim, recorded beside the harness's own evidence, never relied on.", entity: "progress-file", auto: ["PROGRESS.md"] },
  { id: "progress-json", term: "progress.json", def: "The live status the harness rewrites about once a minute for dbench to read. Not committed.", entity: "story-run", auto: ["progress.json"] },
  { id: "provenance", term: "Provenance", def: "Which harness commit and release, and which suite version, each story ran under.", entity: "provenance", auto: ["provenance"] },
  { id: "origin-main", term: "origin/main", def: "The public repo's main branch. Every story's record is pushed to it; the benchmarker reads it; the monitor watches it.", entity: "record" },
  { id: "qwen", term: "Qwen3.8", def: "The model family under test. Variants here: 27B, Flash-Next, Swift 1.0 and Swift 1.5 (retrains of the 27B by UkisAI).", entity: "model" },
  { id: "record", term: "Record", def: "What is committed and pushed to the public repo after every story: the run directory, minus held-out detail, local names and credentials.", entity: "record" },
  { id: "reference-model", term: "Reference model", def: "A frontier model (Claude Opus 5.5, Sonnet 5.5) run through the same harness as the yardstick for local combinations.", entity: "reference", auto: ["reference model", "reference models"] },
  { id: "regression", term: "Regression", def: "An earlier story's held-out test that passed before this story and fails after it. Reported apart from the story's own tests.", entity: "accept", see: ["repair"] },
  { id: "repair", term: "Repair", def: "An earlier held-out test that failed before a story and passes after it. Also: what finalize does to stale records (recomputing time accounting from full logs).", entity: "accept", see: ["regression"] },
  { id: "rescore", term: "Re-score", def: "Testing each story's recorded code again with the held-out suite at the pack's tag, from a clean install, three times.", entity: "rescore", auto: ["re-score", "re-scored", "re-scoring", "re-scores"] },
  { id: "run", term: "Run", def: "One combination's attempt to build a scope of a pack, recorded in `combinations/<combination>/benchmarks/<pack>/<run-id>/`. The same run id resumes.", entity: "run" },
  { id: "run-id", term: "Run id", def: "The name of a run's folder, such as `v2-r5`. Running again with the same id resumes at the first unfinished story.", entity: "run" },
  { id: "sandbox", term: "Sandbox", def: "What confines the agent on every machine: `agent-sandbox`, one policy enforced by macOS `sandbox-exec` or Linux bubblewrap, denying everything the run was not given.", entity: "sandbox", auto: ["sandbox"], see: ["agent-sandbox"] },
  { id: "scope", term: "Scope", def: "A named list of stories a run builds (`scope/<name>.json`). Vidi's `canvas` scope has 11 stories.", entity: "scope" },
  { id: "score-record", term: "Score of record", def: "A run's final commit re-scored after the run on a clean install: the number to rank by, such as 68/75.", entity: "score-record", auto: ["score of record"], see: ["live-score", "guard"] },
  { id: "session", term: "Session", def: "The client's conversation with the model within an attempt. The harness resumes sessions by id after errors and for the stop message.", entity: "session" },
  { id: "settings", term: "Settings", def: "Context, reasoning effort, KV type, draft depth, sampling: what the engine actually applied, read from its command line.", entity: "settings", auto: ["reasoning effort"] },
  { id: "spec", term: "Spec", def: "The written specification the agent builds from. Public, read-only for the agent.", entity: "spec" },
  { id: "speculative-decoding", term: "Speculative decoding", def: "Producing several tokens per step by drafting them cheaply and checking them with the main model. The installer checks that a draft head is live before calling an install good.", auto: ["speculative decoding"], see: ["draft-head"] },
  { id: "spread", term: "Spread (thinking spread, time spread)", def: "How much the same story differs from one finished run of a combination to the next: for each story the variation across runs, then the median over stories. Shown from three finished runs. Read it beside the amount; low spread is not good on its own.", entity: "benchmarker", auto: ["thinking spread", "time spread"] },
  { id: "stall", term: "Stalled", def: "A story stopped by the loop detector: the agent made 8 identical tool calls in a row.", entity: "story-run" },
  { id: "stop-message", term: "Stop message", def: "The one fixed message the agent gets when it stops unfinished. A second unfinished stop ends the story.", entity: "stop-message", auto: ["stop message"], see: ["stop-rule", "nudge"] },
  { id: "stop-rule", term: "Stop rule", def: "The rule (1 October 2026, on main, not yet in a release) that a story ends only on a verified DONE line, with one stop message in between.", entity: "stop-message", auto: ["stop rule"], see: ["done-line"] },
  { id: "story", term: "Story", def: "One unit of the spec: a user-visible feature with a PRD, a design and ordered tasks.", entity: "story" },
  { id: "story-run", term: "Story run", def: "One run's work on one story: the unit everything is measured on.", entity: "story-run", auto: ["story run", "story runs"] },
  { id: "suite-version", term: "Suite version", def: "The tag of the held-out suite a score came from, for example `vidi-v2.0-pre2`. Scores from different versions are not compared.", entity: "heldout", see: ["pack-ref"] },
  { id: "sweep", term: "Sweep", def: "`finalize_pending.py`: the step at the start and end of every run that gives earlier runs with no score of record another try, with a bounded budget.", entity: "finalize", auto: ["the sweep"] },
  { id: "swift", term: "Swift 1.0 and 1.5", def: "UkisAI's retrains of Qwen3.8 27B that think less. Swift 1.5 is a different model from 1.0, so a separate combination.", entity: "model" },
  { id: "task", term: "Task", def: "One ordered step of a story's `tasks.md`, ordered test-first. Its state is judged from workspace evidence.", entity: "task" },
  { id: "telemetry", term: "Telemetry", def: "What the harness records about each run and story. `TELEMETRY.md` lists every field, where it lands and which machines produce it.", entity: "run", auto: ["TELEMETRY.md"] },
  { id: "thinking", term: "Thinking", def: "The reasoning text a model writes before it answers. It stays in the conversation, so a long block is re-read on every later call. Claude's is withheld by the provider.", entity: "conversation" },
  { id: "time-split", term: "Time split", def: "A story's wall time partitioned by owner: compaction, tool, prefill, decode, between sessions, other. The parts always sum to the wall time.", entity: "time-split", auto: ["time split"] },
  { id: "tok-s", term: "tok/s", def: "Tokens per second. 'Generated tok/s' is output tokens over the whole story time, tools included; 'generation tok/s' is engine speed over the model's own time. The benchmark's claim is that neither means much without the quality of what was written.", see: ["decode", "prefill"] },
  { id: "tool-call", term: "Tool call", def: "A request from the model to the client to read a file, edit, write or run a command. One reply can carry several.", entity: "client" },
  { id: "unfit", term: "Machine unfit (exit 75)", def: "The harness's way of saying a guard stopped a story and the machine must recover; dbench waits 5 minutes without counting a restart.", entity: "machine-guard", see: ["machine-guard"] },
  { id: "unscored", term: "Unscored run", def: "A finished run with no score of record because its re-score was spoiled or flagged. `finalize.json` says whether trying again can help.", entity: "finalize", see: ["sweep"] },
  { id: "vidi", term: "Vidi", def: "The first pack: a collaborative whiteboard in the style of Miro, 17 stories in 3 epics. The `canvas` scope builds 11 of them.", entity: "pack", auto: ["Vidi"] },
  { id: "todoodle", term: "Todoodle", def: "The second pack: a to-do app with link-based workspaces, tasks and projects, 11 stories.", entity: "pack", auto: ["Todoodle"] },
  { id: "workspace", term: "Workspace", def: "The agent's git repository for a run, carried from story to story.", entity: "workspace" },
  { id: "wrangler", term: "Wrangler", def: "Cloudflare's local development server, which the spec's apps run on and the held-out suite starts. Agents leave many of them running.", auto: ["Wrangler"] },
  { id: "playwright", term: "Playwright", def: "The browser-test framework the held-out suite and the agent's end-to-end tests use.", auto: ["Playwright"] },
];

